<script setup lang="ts">
import { Link, router, usePage } from '@inertiajs/vue3'
import { ref } from 'vue'
import { ArrowLeft, Edit3, Trash2 } from '@lucide/vue'
interface Related { id: number; name: string }
interface Asset { id: number; description: string; user_name: string | null; serial_number: string | null; acquisition_date: string | null; notes: string | null; photo_path: string | null; category: Related; location: Related; department: Related; brand: Related | null; processor: Related | null; memory: Related | null; position: Related | null; condition: Related }
const props = defineProps<{ asset: Asset }>()
const page = usePage<{ flash?: { success?: string }; auth: { user: { role: string } } }>()
const canManageAssets = ['admin', 'operator'].includes(page.props.auth.user.role)
const isPhotoModalOpen = ref(false)
function destroyAsset(): void {
    if (window.confirm('Yakin ingin menghapus aset ini? Data yang dihapus tidak dapat dikembalikan.')) {
        router.delete(route('assets.destroy', props.asset.id))
    }
}
</script>
<template><div class="min-h-screen"><header class="border-b bg-white/95 px-4 py-4"><div class="mx-auto flex max-w-3xl items-center justify-between"><div class="flex items-center gap-3"><Link :href="route('assets.index')" class="rounded-xl p-2 text-muted-foreground"><ArrowLeft class="size-5" /></Link><div><p class="text-xs uppercase tracking-wider text-primary">Detail Aset</p><h1 class="text-xl font-bold">{{ asset.category.name }}</h1></div></div><div v-if="canManageAssets" class="flex items-center gap-2"><Link :href="route('assets.edit', asset.id)" class="rounded-xl border p-2 text-muted-foreground" title="Edit aset"><Edit3 class="size-5" /></Link><button type="button" class="rounded-xl border border-red-200 p-2 text-red-600 hover:bg-red-50" title="Hapus aset" @click="destroyAsset"><Trash2 class="size-5" /></button></div></div></header><main class="mx-auto max-w-3xl space-y-4 px-4 py-6"><div v-if="page.props.flash?.success" class="rounded-2xl bg-green-50 p-4 text-sm font-medium text-green-700">{{ page.props.flash.success }}</div><section class="rounded-3xl bg-primary p-5 text-primary-foreground"><p class="text-sm opacity-80">{{ asset.category.name }}</p><h2 class="mt-1 text-2xl font-bold">Detail aset</h2><p class="mt-3 text-sm opacity-90">{{ asset.description }}</p></section><button v-if="asset.photo_path" type="button" class="block w-full overflow-hidden rounded-3xl border bg-muted p-2" title="Klik untuk memperbesar foto" @click="isPhotoModalOpen = true"><img :src="route('assets.photo', asset.id)" alt="Foto aset" class="max-h-96 w-full rounded-2xl object-contain transition hover:scale-[1.02]"><span class="block py-2 text-center text-xs text-muted-foreground">Klik foto untuk memperbesar</span></button><section class="grid grid-cols-2 gap-3"><div v-for="item in [{ label: 'Lokasi', value: asset.location.name }, { label: 'Departemen', value: asset.department.name }, { label: 'Kondisi', value: asset.condition.name }, { label: 'Pengguna', value: asset.user_name || '-' }, { label: 'Jabatan', value: asset.position?.name || '-' }, { label: 'Merek', value: asset.brand?.name || '-' }, { label: 'Processor', value: asset.processor?.name || '-' }, { label: 'Memory/RAM', value: asset.memory?.name || '-' }, { label: 'Nomor seri', value: asset.serial_number || '-' } ]" :key="item.label" class="rounded-2xl border bg-card p-4"><p class="text-xs text-muted-foreground">{{ item.label }}</p><p class="mt-1 font-medium">{{ item.value }}</p></div></section><section v-if="asset.notes || asset.acquisition_date" class="rounded-2xl border bg-card p-4"><p v-if="asset.acquisition_date" class="text-sm"><span class="text-muted-foreground">Tanggal perolehan:</span> {{ asset.acquisition_date }}</p><p v-if="asset.notes" class="mt-3 text-sm"><span class="text-muted-foreground">Catatan:</span> {{ asset.notes }}</p></section></main><div v-if="isPhotoModalOpen && asset.photo_path" class="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4" role="dialog" aria-modal="true" aria-label="Foto aset ukuran besar" @click.self="isPhotoModalOpen = false"><button type="button" class="absolute right-4 top-4 rounded-full bg-white/90 px-4 py-2 text-2xl leading-none text-black" aria-label="Tutup foto" @click="isPhotoModalOpen = false">&times;</button><img :src="route('assets.photo', asset.id)" alt="Foto aset ukuran besar" class="max-h-[90vh] max-w-[95vw] rounded-2xl object-contain shadow-2xl"></div></div></template>
